INSERT INTO `v1_d8459a568be773c236f69a1345d5cd0af3c6374620360a8bf8cbea1cdd7512d6` VALUES (24, 1, 100, 0, "エリコ", 7, "2024/03/31 12:00:00", "訓練成功、おめでとうございます\n褒めるべき時にはしっかり褒めるのも\n教官の務めですものね。それとも、\n罵られる方が好みですか？　クスクス", 10.85, 0, 129901, "2030/12/17 14:59:59", 10142, 100);
INSERT INTO `v1_d8459a568be773c236f69a1345d5cd0af3c6374620360a8bf8cbea1cdd7512d6` VALUES (24, 1, 101, 0, "エリコ", 2, "2024/03/31 12:00:00", "厳しい訓練も、終わってみれば\n短く感じるものですわね。\n正直、私は暴れ足りないくらい…\nいえ、何でもありませんわ。クスクス", 11.15, 0, 129901, "2030/12/17 14:59:59", 10142, 101);
INSERT INTO `v1_d8459a568be773c236f69a1345d5cd0af3c6374620360a8bf8cbea1cdd7512d6` VALUES (24, 7, 102, 0, "エリコ", 5, "2024/03/31 12:00:00", "行く手を阻む忌々しい邪魔者を\n蹴散らして、見事ゴールイン…！\nまるで私とあのおかたの人生を\n象徴するような道のりでした…", 6.4, 0, 129901, "2030/12/17 14:59:59", 10142, 102);
INSERT INTO `v1_d8459a568be773c236f69a1345d5cd0af3c6374620360a8bf8cbea1cdd7512d6` VALUES (24, 3, 103, 0, "エリコ", 3, "2024/03/31 12:00:00", "まったくもって不甲斐ない結果です\nしかし、挽回の機会はまだありますわ\n次はゴミ虫の地位から脱却できるよう\n死力を尽くしなさい。いいですね？", 0, 0, 129901, "2030/12/17 14:59:59", 10142, 103);
INSERT INTO `v1_d8459a568be773c236f69a1345d5cd0af3c6374620360a8bf8cbea1cdd7512d6` VALUES (24, 2, 104, 0, "エリコ", 8, "2024/03/31 12:00:00", "クスクス…ああご心配なさらず\nなんとも情けない成績を残す輩には\nどんな罰が相応しいか、考えている\nだけですので…クスクスクス", 2.43, 0, 129901, "2030/12/17 14:59:59", 10142, 104);
INSERT INTO `v1_d8459a568be773c236f69a1345d5cd0af3c6374620360a8bf8cbea1cdd7512d6` VALUES (24, 4, 105, 0, "エリコ", 3, "2024/03/31 12:00:00", "私が教官として認められなければ、\nあのおかたを失望させてしまう…\nそれだけはあってはなりません\nあなた方も、わかっていますわね？", 9.08, 0, 129901, "2030/12/17 14:59:59", 10142, 105);
INSERT INTO `v1_d8459a568be773c236f69a1345d5cd0af3c6374620360a8bf8cbea1cdd7512d6` VALUES (24, 6, 106, 0, "エリコ", 6, "2024/03/31 12:00:00", "まずまずの結果ではありますが、\nこの程度で満足してもらっては\n困りますわ。エリコ班の一員として、\nより高みを目指していただきますので", 0, 0, 129901, "2030/12/17 14:59:59", 10142, 106);
INSERT INTO `v1_d8459a568be773c236f69a1345d5cd0af3c6374620360a8bf8cbea1cdd7512d6` VALUES (24, 3, 107, 0, "エリコ", 8, "2024/03/31 12:00:00", "私の指導を受けながら、この結果は…\nもっと真剣に考えねばなりませんね\nあなた方が怠けずにいるには、\nどんなしつけが必要かを…クスクス", 10.6, 0, 129901, "2030/12/17 14:59:59", 10142, 107);
INSERT INTO `v1_d8459a568be773c236f69a1345d5cd0af3c6374620360a8bf8cbea1cdd7512d6` VALUES (24, 6, 108, 0, "エリコ", 4, "2024/03/31 12:00:00", "ひとまず訓練をこなしたご褒美か、\n実力を出しきれたとは言えない罰か…\nみなさんにどちらを与えるべきか\n少し悩む結果ですわね", 7.54, 0, 129901, "2030/12/17 14:59:59", 10142, 108);
INSERT INTO `v1_d8459a568be773c236f69a1345d5cd0af3c6374620360a8bf8cbea1cdd7512d6` VALUES (24, 2, 109, 0, "エリコ", 7, "2024/03/31 12:00:00", "なかなかいい戦いぶりでしたわ\nこれもあなた方の頑張りと、何より\n優秀な教官である私の教育の賜物\nそうですわね？　クスクスクス…", 11.5, 0, 129901, "2030/12/17 14:59:59", 10142, 109);
INSERT INTO `v1_d8459a568be773c236f69a1345d5cd0af3c6374620360a8bf8cbea1cdd7512d6` VALUES (24, 2, 110, 0, "エリコ", 1, "2024/03/31 12:00:00", "これだけ進めたのならば合格点ですわ\nでも、もっと高みを目指したいと\n思っているのなら…さらなる訓練にも\n付き合って差し上げましょう", 8.83, 0, 129901, "2030/12/17 14:59:59", 10142, 110);
INSERT INTO `v1_d8459a568be773c236f69a1345d5cd0af3c6374620360a8bf8cbea1cdd7512d6` VALUES (24, 1, 111, 0, "エリコ", 2, "2024/03/31 12:00:00", "未熟で頼りなかったあなた方が、\n見違えるように成長しました\nなるほど…これこそが、教官冥利に\n尽きるという気持ちなのですね", 6.68, 0, 129901, "2030/12/17 14:59:59", 10142, 111);
INSERT INTO `v1_d8459a568be773c236f69a1345d5cd0af3c6374620360a8bf8cbea1cdd7512d6` VALUES (24, 6, 112, 0, "エリコ", 2, "2024/03/31 12:00:00", "まさかあなた方が、私の予想すら\n超える力を発揮するとは…驚きました\nもはやゴミ虫などではありません\n一人前の騎士として胸を張りなさい", 8.8, 0, 129901, "2030/12/17 14:59:59", 10142, 112);
INSERT INTO `v1_d8459a568be773c236f69a1345d5cd0af3c6374620360a8bf8cbea1cdd7512d6` VALUES (24, 2, 113, 0, "エリコ", 1, "2024/03/31 12:00:00", "クスクス、見事な働きです\nみなさんならできると信じていました\n他でもない私の指導を受けた、\nエリコ班の優秀な新兵なのですから", 8.9, 0, 129901, "2030/12/17 14:59:59", 10142, 113);
INSERT INTO `v1_d8459a568be773c236f69a1345d5cd0af3c6374620360a8bf8cbea1cdd7512d6` VALUES (24, 2, 114, 0, "エリコ", 5, "2024/03/31 12:00:00", "なんてすばらしい成績…！\n今日という日は『あのおかたを想い\nエリコが限界を超えた記念日』として\n歴史に刻まれることでしょう…！", 3.7, 0, 129901, "2030/12/17 14:59:59", 10142, 114);
INSERT INTO `v1_d8459a568be773c236f69a1345d5cd0af3c6374620360a8bf8cbea1cdd7512d6` VALUES (24, 1, 200, 0, "マコト", 2, "2024/03/31 12:00:00", "よし、いい訓練になったな\nおまえたちもよく動けてたし、\nちゃんと成長できてると思うぜ\nその調子で頑張れよっ", 7.6, 0, 129801, "2030/12/17 14:59:59", 10142, 200);
INSERT INTO `v1_d8459a568be773c236f69a1345d5cd0af3c6374620360a8bf8cbea1cdd7512d6` VALUES (24, 2, 201, 0, "マコト", 1, "2024/03/31 12:00:00", "ひとまずゴールおめでとう！\nでも、努力は継続してこそだからな\nおまえたちにやる気があるなら、\n何度だって付き合ってやるよ", 2.25, 0, 129801, "2030/12/17 14:59:59", 10142, 201);
INSERT INTO `v1_d8459a568be773c236f69a1345d5cd0af3c6374620360a8bf8cbea1cdd7512d6` VALUES (24, 2, 202, 0, "マコト", 1, "2024/03/31 12:00:00", "行軍訓練はこれにて完了！\n…なーんて思ってないよな？\n学んだことが体に染みつくまで\n地道に繰り返すのが練習ってもんさ", 3.28, 0, 129801, "2030/12/17 14:59:59", 10142, 202);
INSERT INTO `v1_d8459a568be773c236f69a1345d5cd0af3c6374620360a8bf8cbea1cdd7512d6` VALUES (24, 4, 203, 0, "マコト", 1, "2024/03/31 12:00:00", "みんなに無理をさせちまったか…\nでもこれで諦めることはないぜ\n次はきっとうまくいく。そう信じて\n鍛え続ければ、道は開けるはずだ！", 2.98, 0, 129801, "2030/12/17 14:59:59", 10142, 203);
INSERT INTO `v1_d8459a568be773c236f69a1345d5cd0af3c6374620360a8bf8cbea1cdd7512d6` VALUES (24, 4, 204, 0, "マコト", 1, "2024/03/31 12:00:00", "こいつは悔しい結果だな…\nま、反省点はいろいろあったし\nひとつずつ乗り越えていこう\nあたしたちで力を合わせて、なっ！", 3, 0, 129801, "2030/12/17 14:59:59", 10142, 204);
INSERT INTO `v1_d8459a568be773c236f69a1345d5cd0af3c6374620360a8bf8cbea1cdd7512d6` VALUES (24, 1, 205, 0, "マコト", 2, "2024/03/31 12:00:00", "おまえたちはまだ未熟な訓練兵、\n失敗を必要以上に悔やむことはねえよ\nでも実戦じゃこうはいかないからな\n次は気合を入れ直していけよっ！", 10.3, 0, 129801, "2030/12/17 14:59:59", 10142, 205);
INSERT INTO `v1_d8459a568be773c236f69a1345d5cd0af3c6374620360a8bf8cbea1cdd7512d6` VALUES (24, 6, 206, 0, "マコト", 1, "2024/03/31 12:00:00", "これがおまえたちの全力？\nいやいや、そんなはずはないよなっ\nおまえらならもっと強くなれる！\nあたしが言うんだ、間違いないぜ！", 2.93, 0, 129801, "2030/12/17 14:59:59", 10142, 206);
INSERT INTO `v1_d8459a568be773c236f69a1345d5cd0af3c6374620360a8bf8cbea1cdd7512d6` VALUES (24, 3, 207, 0, "マコト", 1, "2024/03/31 12:00:00", "おまえたちの実力を考えりゃ、\nベストを尽くせたとは言えない成績だ\nなら、次やるべきことも決まってる\n気持ちを切り替えて、鍛え直すんだ！", 9.3, 0, 129801, "2030/12/17 14:59:59", 10142, 207);
INSERT INTO `v1_d8459a568be773c236f69a1345d5cd0af3c6374620360a8bf8cbea1cdd7512d6` VALUES (24, 4, 208, 0, "マコト", 1, "2024/03/31 12:00:00", "まだまだ課題がある内容だったな～\n無駄な動き、判断の遅れ…\nそういうのをしっかり直していけば、\n記録ももっと伸びるはずだっ", 6.9, 0, 129801, "2030/12/17 14:59:59", 10142, 208);
INSERT INTO `v1_d8459a568be773c236f69a1345d5cd0af3c6374620360a8bf8cbea1cdd7512d6` VALUES (24, 2, 209, 0, "マコト", 2, "2024/03/31 12:00:00", "ここまでいけりゃ、合格点！\nむしろ、最初の頼りなさを思えば\nすげえ成長してるんじゃねえか？\n胸を張れる結果だと思うぜっ！", 0, 0, 129801, "2030/12/17 14:59:59", 10142, 209);
INSERT INTO `v1_d8459a568be773c236f69a1345d5cd0af3c6374620360a8bf8cbea1cdd7512d6` VALUES (24, 1, 210, 0, "マコト", 2, "2024/03/31 12:00:00", "なかなかハードな訓練だったけど、\nみんなしっかりついてこられたな\n地道に続けた基礎トレの成果が\n形になってる、その証だぜっ", 5.95, 0, 129801, "2030/12/17 14:59:59", 10142, 210);
INSERT INTO `v1_d8459a568be773c236f69a1345d5cd0af3c6374620360a8bf8cbea1cdd7512d6` VALUES (24, 2, 211, 0, "マコト", 1, "2024/03/31 12:00:00", "今回の訓練もよく頑張ったな！\nしっかり休んで次に備えろよ！\nなんつーか、教え子が成長してくのを\n見るのは楽しいもんだな…", 6.73, 0, 129801, "2030/12/17 14:59:59", 10142, 211);
INSERT INTO `v1_d8459a568be773c236f69a1345d5cd0af3c6374620360a8bf8cbea1cdd7512d6` VALUES (24, 2, 212, 0, "マコト", 2, "2024/03/31 12:00:00", "おまえら、すげえじゃねえか！\nこれならもう、ひよっこ新兵なんて\n言えねえな。きっと騎士団でも\n大活躍間違いなしだぜ！", 0, 0, 129801, "2030/12/17 14:59:59", 10142, 212);
INSERT INTO `v1_d8459a568be773c236f69a1345d5cd0af3c6374620360a8bf8cbea1cdd7512d6` VALUES (24, 1, 213, 0, "マコト", 2, "2024/03/31 12:00:00", "敵との戦い方、状況判断の正確さ\n何より根性…どれも最高だったぞ！\nうかうかしてたら、教官のあたしまで\n追い抜かれちまうかもな…へへっ", 6.65, 0, 129801, "2030/12/17 14:59:59", 10142, 213);
INSERT INTO `v1_d8459a568be773c236f69a1345d5cd0af3c6374620360a8bf8cbea1cdd7512d6` VALUES (24, 6, 214, 0, "マコト", 1, "2024/03/31 12:00:00", "あたしの指導が良かった？\nいやいや、ここまで強くなれたのは、\n他でもないおまえたち自身が努力した\nおかげだよ。改めて…おめでとうっ！", 3.05, 0, 129801, "2030/12/17 14:59:59", 10142, 214);
